import java.util.*; public class Q10_SmartHomeDevices{interface Device{void turnOn();void turnOff();}static class Fan implements Device{public void turnOn(){System.out.println("Fan is now ON");}public void turnOff(){System.out.println("Fan is now OFF");}}static class Light implements Device{public void turnOn(){System.out.println("Light is now ON");}public void turnOff(){System.out.println("Light is now OFF");}}public static void main(String[]x){Scanner s=new Scanner(System.in);while(s.hasNextLine()){String t=s.nextLine();if(t.isBlank())continue;Device d=t.equalsIgnoreCase("Fan")?new Fan():new Light();d.turnOn();d.turnOff();}}}
